const input = items[0].json.body || items[0].json;
const text = String(input.text || '').trim();
const pendingField = input.runtime?.pending?.field;
const ctx = input.runtime?.context || {};

const extractRadius = (s) => {
  const m = String(s || '').match(/(\d{1,4})\s*(км|km)?/i);
  return m ? Number(m[1]) : null;
};

const normalizeCity = (s) => {
  const v = String(s || '').trim();
  if (!v) return null;
  const low = v.toLowerCase();
  if (low === 'аэропорт' || low === 'аэропорты' || low === 'airport' || low === 'airports') return null;
  return v;
};

let radius = null;
let city = null;

if (pendingField === 'radius_km') {
  radius = extractRadius(text);
  city = normalizeCity(ctx.city) || null;
} else if (pendingField === 'city') {
  city = normalizeCity(text) || null;
  radius = (typeof ctx.radius_km === 'number' ? ctx.radius_km : extractRadius(text));
} else {
  radius = extractRadius(text);

  // Heuristic: try to detect city from keywords first.
  const low = text.toLowerCase();
  if (low.includes('моск')) city = 'Москва';
  else if (low.includes('петер') || low.includes('питер')) city = 'Санкт-Петербург';
  else {
    const words = text.split(/\s+/).filter(Boolean);
    city = words.length ? normalizeCity(words[words.length - 1]) : null;
  }
}

return [{ json: { ...input, params: { city, radius_km: radius } } }];

