const input = items[0].json;
const airports = input.airports;
const weather = input.weather;
const trace_id = input.trace_id || airports?.trace_id || weather?.trace_id;
const request_id = input.request_id || airports?.request_id || weather?.request_id;
const session_id = input.session_id || airports?.session_id || weather?.session_id;
