const errors = [];
if (!airports?.ok) errors.push({ code: airports?.error?.code || 'tool_failed', message: airports?.error?.message || 'Airports tool failed' });
if (!weather?.ok) errors.push({ code: weather?.error?.code || 'tool_failed', message: weather?.error?.message || 'Weather tool failed' });
if (errors.length) {
  return [{ json: {
    trace_id,
    correlation_id,
    request_id,
    session_id,
    ts_ms: Date.now(),
    status: 'FAILED',
    result: '',
    client_handler: { command: 'SHOW_ERROR_MESSAGE', payload: { message: errors[0].message } },
    client_events: [],
    next_runtime: { active_workflow_id: null, pending: null, context: input.runtime?.context || null, version: input.runtime?.version || 1 },
    errors
  }}];
}
const airportsData = airports?.data?.data?.airports || airports?.data?.airports || [];
const weatherData = weather?.data?.data?.weather || weather?.data?.weather || weather?.data || {};
return [{ json: {
  trace_id,
  correlation_id,
  request_id,
  session_id,
  ts_ms: Date.now(),
  status: 'DONE',
  result: '',
  client_handler: { command: 'SHOW_AIRPORTS', payload: { data: { airports: airportsData, weather: weatherData } } },
  client_events: [ { command: 'SHOW_MESSAGE', payload: { message: 'Found airports and weather.' } } ],
